// Leptos views are deeply nested types, release builds need more room
#![recursion_limit = "256"]

pub mod api;
pub mod app;
pub mod audio;
pub mod components;
pub mod lang;
pub mod model;
pub mod pages;
pub mod seo;
#[cfg(feature = "ssr")]
pub mod server;
pub mod state;

/// The `i18n` module generated by build.rs from locales/. Not our code, and a single 5 MB line:
/// a diagnostic in it repeats that line, so linting it took gigabytes. Exempt from the strict
/// workspace lints.
#[allow(
    clippy::all,
    clippy::pedantic,
    clippy::nursery,
    rust_2018_idioms,
    unused_qualifications,
    unreachable_pub,
    missing_debug_implementations,
    trivial_casts,
    trivial_numeric_casts
)]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/i18n/mod.rs"));
}
pub use generated::i18n;

#[cfg(feature = "hydrate")]
#[wasm_bindgen::prelude::wasm_bindgen]
pub fn hydrate() {
    console_error_panic_hook::set_once();
    leptos::mount::hydrate_body(app::App);
}
